// Import of required libraries
import { expect, test, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { fillOwnerForm, openNewOwnerForm } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(156000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // The PR states the email field is optional, so an owner saved without one
    // must still be created and still display normally.
    await openNewOwnerForm(page, baseUrl);
    await fillOwnerForm(page, "Noemail", "Optional", "2 Optional Rd", "Monona", "6085550222", "");

    const addOwnerButton = page.getByRole("button", { name: "Add Owner" });
    await expect(addOwnerButton).toBeEnabled();

    const responsePromise0 = page.waitForResponse("**/petclinic/api/owners**");
    await addOwnerButton.click();
    const response0 = await responsePromise0;

    // Omitting email is accepted and no email value is invented for the owner.
    expect(response0.status()).toBe(201);
    const createdOwner = await response0.json();
    expect(createdOwner.firstName).toBe("Noemail");
    expect(createdOwner.email ?? null).toBeNull();

    await page
        .locator('#ownersTable tbody tr')
        .filter({ hasText: 'Noemail Optional' })
        .last()
        .getByRole('link', { name: 'Noemail Optional' })
        .click();

    // "existing owners without one continue to display and save normally" — the
    // detail page must still render the owner. It renders every cell blank because
    // OwnerDetailComponent never notifies change detection after getOwnerById
    // resolves, so this fails.
    const detailTable = page.locator('app-owner-detail table').first();
    await expect(
        detailTable.locator('tr').filter({ has: page.locator('th', { hasText: /^Name$/ }) }).locator('td'),
    ).toHaveText('Noemail Optional');

    // The Email cell renders empty for an owner that has no email.
    await expect(
        detailTable.locator('tr').filter({ has: page.locator('th', { hasText: /^Email$/ }) }).locator('td'),
    ).toHaveText('');
});
